    P()
    P(f"2. {B('அளவு வேறுபாடு (Divergence):')} விலை புதிய உச்சம் ஆனால் அளவு குறைவாக இருந்தால் — போக்கு பலவீனமானது. Smart money விநியோகிக்க ஆரம்பித்துவிட்டார்கள் என்று அர்த்தம். விலை புதிய தாழ்வு ஆனால் அளவு குறைவாக இருந்தால் — விற்பனை தீர்ந்துவிட்டது.")
    P()
    P(f"3. {B('உச்ச அளவு (Climax Volume):')} மிக அதிக அளவு பெரும்பாலும் மாற்றத்தை குறிக்கிறது. காளை சந்தையின் உச்சியில் climax volume = euphoria (எல்லாரும் வாங்கிவிட்டார்கள்). கரடி சந்தையின் அடியில் climax volume = capitulation (எல்லாரும் விற்றுவிட்டார்கள்).")
    P()

    H3("அளவு குறிகாட்டிகள்:")
    P()
    P(f"{B('OBV (On-Balance Volume):')} Cumulative volume indicator. உயர் நாளில் அளவு கூட்டவும், தாழ் நாளில் அளவு கழிக்கவும். OBV உயர்வது = accumulation. OBV தாழ்வது = distribution. OBV-க்கும் விலைக்கும் divergence = வலுவான குறிப்பு.")
    P()
    P(f"{B('Volume Profile:')} ஒவ்வொரு விலை நிலையிலும் அளவைக் காட்டுகிறது. High Volume Nodes (HVN) = ஆதரவு/எதிர்ப்பு மண்டலங்கள். Point of Control (POC) = அதிக அளவு விலை. Low Volume Nodes (LVN) = விலை வேகமாக கடந்து செல்லும்.")
    P()
    P(f"{B('VWAP (Volume Weighted Average Price):')} அளவு-எடையிடப்பட்ட சராசரி விலை. விலை VWAP-க்கு மேலே = காளை நிலை. கீழே = கரடி நிலை. நிறுவன வர்த்தகர்கள் VWAP-ஐ குறிப்பாகப் பயன்படுத்துவார்கள்.")
    P()

    HR()
    P()

    H2("1.6 பல கால அளவிலான பகுப்பாய்வு (Multi-Timeframe Analysis)")
    P()
    P("ஒரே வரைபடத்தில் எல்லா தகவல்களும் இருக்காது. வெவ்வேறு கால அளவுகள் வெவ்வேறு கதைகளைச் சொல்லும். உயர் கால அளவின் போக்கை எதிர்த்து வர்த்தகம் செய்வது மிகவும் ஆபத்தானது. Multi-timeframe analysis-ன் முக்கிய நோக்கம்: உயர் கால அளவில் போக்கை அடையாளம் கண்டு, கீழ் கால அளவில் துல்லியமான நுழைவைக் கண்டுபிடிப்பது.")
    P()
    P(f"{B('கால அளவு படிநிலை:')}")
    P(f"{B('உயர் கால அளவு (வாராந்திர/மாதாந்திர):')} முதன்மை போக்கு. முக்கிய S/R நிலைகள். எந்த திசையில் வர்த்தகம் செய்ய வேண்டும் என்று இது சொல்லும்.")
    P(f"{B('நுழைவு கால அளவு (தினசரி/4-மணி):')} இடைநிலை போக்கு. வடிவ அடையாளம். வரைபட வடிவங்கள், மெழுகுவர்த்தி வடிவங்கள், குறிகாட்டி குறிப்புக்கள் — இவை அனைத்தும் இங்கு பார்க்க வேண்டியவை.")
    P(f"{B('கீழ் கால அளவு (மணி/15-நிமிடம்):')} துல்லியமான நுழைவு. நட்ட வரம்பு நிர்ணயம். உயர் கால அளவில் குறிப்பு கிடைத்ததும், கீழ் கால அளவில் நுழைவு தூண்டுதலுக்காக காத்திருக்க வேண்டும்.")
    P()
    P("பொன் விதி: உயர் கால அளவின் போக்குக்கு எதிராக வர்த்தகம் செய்யாதீர்கள். வாராந்திர வரைபடம் ஏறுமுகத்தில் இருந்தால், தினசரி வரைபடத்தில் வீழ்ச்சிகளில் வாங்குங்கள். மூன்று கால அளவுகளும் ஒரே திசையில் இருந்தால் = அதிக நிகழ்தகவு வர்த்தகம்.")
    P()

    HR()
    P()

    H2("1.7 மாற்ற வரைபட வடிவங்கள் (Reversal Chart Patterns)")
    P()
    P("மாற்ற வடிவங்கள் தற்போதைய போக்கின் முடிவைக் குறிக்கின்றன. இவை போக்கின் முடிவில் வரும், மற்றும் திசை மாற்றம் ஆகப் போகிறது என்று சொல்லும். மாற்ற வடிவத்தின் நம்பகத்தன்மைக்கு அளவு உறுதிப்படுத்தல் மிகவும் முக்கியம். வடிவம் முழுமை அடைந்ததும் (முறிவு), அளவு அதிகமாக இருக்க வேண்டும். இல்லையெனில் பொய் குறிப்பு ஆக வாய்ப்பு அதிகம்.")
    P()

    H3("தலை மற்றும் தோள்கள் மேல் (Head and Shoulders Top)")
    P()
    P("இது மிகவும் நம்பகமான மாற்ற வடிவம். மூன்று உச்சிகள்: இடது தோள் (மிதமான உயரம்), தலை (மிக உயர்ந்த உச்சி), வலது தோள் (மிதமான உயரம்). Neckline — இரண்டு அடிகளை இணைக்கும் கோடு. Neckline-க்குக் கீழே விலை மூடியதும் வடிவம் முழுமை அடையும். இலக்கு = neckline-லிருந்து தலைக்கு உள்ள தூரம், neckline-லிருந்து கீழே அளக்கப்படும்.")
    P()
    TP("தலை மற்றும் தோள்கள் வடிவம் மிகவும் நம்பகமான மாற்ற வடிவங்களில் ஒன்றாகும். இது மூன்று உச்சிகளை கொண்டது — இடது தோள், தலை, வலது தோள். கழுத்துக் கோடு உடைந்த பிறகு விலை கீழே செல்லும். இலக்கு தூரம் கழுத்துக் கோட்டிலிருந்து தலை வரை உள்ள தூரத்திற்கு சமமாகும்.")
    CHART_DESC("தலை மற்றும் தோள்கள் வடிவத்தின் விளக்கம் — மூன்று உச்சிகள் மற்றும் கழுத்துக் கோட்டை காட்டுகிறது.", V.head_shoulders, 450, 250)
    P(f"{B('அளவு பகுப்பாய்வு:')} இடது தோளில் மிதமான அளவு. தலையில் அளவு பொதுவாக குறையும். வலது தோளில் அளவு இன்னும் குறையும். Neckline முறிவு ஏற்படும் போது அளவு அதிகரிக்க வேண்டும் — இது உறுதிப்படுத்தல்.")
    P()
    P(f"{B('உளவியல்:')} இடது தோள் — 'இன்னும் ஏற்றம் தான்' என்று மக்கள் நினைப்பார்கள். தலை — 'இந்த முறை வித்தியாசம்' என்று FOMO வந்து எல்லாரும் வாங்குவார்கள். வலது தோள் — உற்சாகம் குறையும், smart money மெதுவாக விற்க ஆரம்பிப்பார்கள். Neckline முறிவு — பயம் வரும், panic selling ஆரம்பிக்கும்.")
    P()
    P(f"{B('தலைகீழ் தலை மற்றும் தோள்கள் (Inverse H&S):')} கரடி சந்தையின் அடியில் வரும். இடது தோள், தலை (மிக தாழ்ந்த அடி), வலது தோள் அடி. Neckline (எதிர்ப்பு) உடைக்கப்பட்டதும் வாங்கும் குறிப்பு. இலக்கு = neckline-லிருந்து தலைக்கு உள்ள தூரம், மேலே அளக்கப்படும்.")
    P()

    H3("இரட்டை மேடு (Double Top)")
    P()
    P("விலை ஒரு நிலையில் எதிர்ப்பாகி கீழே வந்து, மறுபடியும் அதே நிலையில் எதிர்ப்பானால் Double top. Neckline உடைக்கப்பட்டதும் விற்பனை குறிப்பு. இரண்டாவது உச்சியில் அளவு பொதுவாக குறைவாக இருக்கும். உச்சிகளுக்கு இடையே குறைந்தது 3 வாரங்கள் இடைவெளி தேவை.")
    P()
    TP("இரட்டை மேடு வடிவம் ஒரு முக்கியமான மாற்ற வடிவமாகும். விலை ஒரு நிலையில் இரண்டு முறை எதிர்ப்பை சந்தித்து தோல்வியடைகிறது. இரண்டாவது உச்சியில் அளவு குறைவாக இருக்கும். கழுத்துக் கோடு உடைந்த பிறகு விற்பனை குறிப்பு உறுதியாகும்.")
    CHART_DESC("இரட்டை மேடு வடிவத்தின் விளக்கம் — இரண்டு உச்சிகள் மற்றும் கழுத்துக் கோட்டை காட்டுகிறது.", V.double_top, 450, 220)

    H3("இரட்டை அடி (Double Bottom)")
    P()
    P("விலை ஒரு நிலையில் ஆதரவாகி மேலே போய், மறுபடியும் அதே நிலையில் ஆதரவானால் Double bottom. Neckline-க்கு மேலே உடைக்கப்பட்டதும் வாங்கும் குறிப்பு. இரண்டாவது அடியில் அளவு பொதுவாக குறைவு.")
    P()
    TP("இரட்டை அடி வடிவம் இரட்டை மேட்டின் எதிர் வடிவமாகும். விலை ஒரு நிலையில் இரண்டு முறை ஆதரவை சந்தித்து மீள்கிறது. கழுத்துக் கோடு மேலே உடைந்த பிறகு வாங்கும் குறிப்பு உறுதியாகும். இரண்டாவது அடியில் அளவு குறைவாக இருப்பது பொதுவானது.")
    CHART_DESC("இரட்டை அடி வடிவத்தின் விளக்கம் — இரண்டு அடிகள் மற்றும் கழுத்துக் கோட்டை காட்டுகிறது.", V.double_bottom, 450, 220)

    H3("வட்ட அடி (Rounding Bottom / Saucer)")
    P()
    P("மெதுவான, படிப்படியான அடி உருவாக்கம் — வாரங்கள் அல்லது மாதங்கள். 'U' வடிவம். ஏறுமுக போக்குக்கு முன் வரும். அளவு படிப்படியாக அதிகரிக்கும். மிகவும் நம்பகமானது — smart money மெதுவாக accumulate பண்ணுவதைக் காட்டுகிறது.")
    P()

    H3("V-மாற்றம் (V-Reversal) மற்றும் தீவு மாற்றம் (Island Reversal)")
    P()
    P("V-Reversal: கூர்மையான வீழ்ச்சி மற்றும் உடனடி கூர்மையான மீட்சி. வர்த்தகம் செய்வது கடினம் — பெரும்பாலும் செய்திகளால் ஏற்படும். தெளிவான வடிவம் இல்லை. Island Reversal: விலை இடைவெளியுடன் மேலே/கீழே போய், சில நாட்கள்/வாரங்கள் வர்த்தகம் ஆகி, பிறகு இடைவெளியுடன் மாற்றம். மிகவும் அரிதானது ஆனால் மிகவும் நம்பகமானது.")
    P()

    HR()
    P()

    H2("1.8 தொடர்ச்சி வரைபட வடிவங்கள் (Continuation Chart Patterns)")
    P()
    P("தொடர்ச்சி வடிவங்கள் போக்கின் நடுவில் வரும். போக்கு ஒரு சிறிய இடைவெளி எடுத்து மீண்டும் தொடரும். இவை 'ஓய்வு' வடிவங்கள் — போக்கின் ஆற்றல் மீண்டும் நிரப்பப்படும் இடம். தொடர்ச்சி வடிவங்களின் நம்பகத்தன்மை அதிகமானது.")
    P()

    H3("கொடிகள் மற்றும் இறக்கைகள் (Flags and Pennants)")
    P()
    P(f"{B('காளை கொடி (Bull Flag):')} கூர்மையான கிட்டத்தட்ட செங்குத்து நகர்வு (flagpole), பின்னர் சிறிய செவ்வக ஒருங்கிணைவு (flag) போக்குக்கு எதிராக சாய்ந்து. கொடியில் அளவு குறைவு, முறிவில் அதிகம். இலக்கு = flagpole உயரம். {B('இறக்கை (Pennant):')} கூர்மையான நகர்வு (pole), பின்னர் சிறிய சமச்சீர் முக்கோணம் (pennant). அதே அளவு முறை.")
    P()

    H3("முக்கோணங்கள் (Triangles)")
    P()
    P(f"{B('ஏறுமுக முக்கோணம்:')} தட்டையான எதிர்ப்பு + உயர்ந்த அடிகள். காளை நிலை. மேல்நோக்கி முறிவு. {B('இறங்குமுக முக்கோணம்:')} தட்டையான ஆதரவு + தாழ்ந்த உச்சிகள். கரடி நிலை. கீழ்நோக்கி முறிவு. {B('சமச்சீர் முக்கோணம்:')} தாழ்ந்த உச்சிகள் + உயர்ந்த அடிகள். முறிவு திசை நிச்சயமற்றது. அளவு உறுதிப்படுத்தலுடன் முறிவில் நுழையவும்.")
    P()
    TP("முக்கோண வடிவங்கள் தொடர்ச்சி வடிவங்கள் ஆகும். விலை ஒரு முக்கோண வடிவத்தில் ஒருங்கிணைந்த பிறகு முந்தைய போக்கின் திசையில் வெடிக்கும். ஏறுமுக முக்கோணம், இறங்குமுக முக்கோணம், மற்றும் சமச்சீர் முக்கோணம் ஆகிய மூன்று வகைகள் உள்ளன.")
    CHART_DESC("சமச்சீர் முக்கோண வடிவத்தின் விளக்கம் — விலை ஒருங்கிணைந்து பின்னர் வெடிப்பதை காட்டுகிறது.", V.triangle, 380, 220)

    H3("ஆப்புகள் (Wedges)")
    P()
    P(f"{B('ஏறுமுக ஆப்பு:')} உயர்ந்த உச்சிகள் + உயர்ந்த அடிகள் ஆனால் ஒருங்கிணைகின்றன. கரடி நிலை. அளவு குறைகிறது. ஏறுமுக போக்குகளின் முடிவில் பொதுவானது. {B('இறங்குமுக ஆப்பு:')} தாழ்ந்த உச்சிகள் + தாழ்ந்த அடிகள் ஆனால் ஒருங்கிணைகின்றன. காளை நிலை. இறங்குமுக போக்குகளின் முடிவில் பொதுவானது.")
    P()

    H3("கோப்பை மற்றும் கைப்பிடி (Cup and Handle)")
    P()
    P("U-வடிவ அடி (cup) → சிறிய ஒருங்கிணைவு (handle). மாதக்கணக்கான வடிவம். கோப்பை 'U' வடிவமாக இருக்க வேண்டும் (படிப்படியான accumulation). கைப்பிடி கீழ்நோக்கி சாய்ந்திருக்க வேண்டும் (பலவீனமானவர்களை வெளியேற்றுதல்). கைப்பிடி முறிவில் வாங்கவும். மிகவும் காளை நிலை வடிவம்.")
    P()
    TP("கோப்பை மற்றும் கைப்பிடி வடிவம் ஒரு மிகவும் நம்பகமான தொடர்ச்சி வடிவமாகும். U-வடிவ கோப்பை படிப்படியான குவிப்பை குறிக்கிறது. கைப்பிடி பலவீனமான வர்த்தகர்களை வெளியேற்றுகிறது. கைப்பிடி முறிவில் வாங்குவது சிறந்த நுழைவு புள்ளியாகும்.")
    CHART_DESC("கோப்பை மற்றும் கைப்பிடி வடிவத்தின் விளக்கம் — U-வடிவ கோப்பை மற்றும் சிறிய கைப்பிடியை காட்டுகிறது.", V.cup_handle, 400, 220)

    H3("இடைவெளி வடிவங்கள் (Gap Patterns)")
    P()
    P(f"{B('Breakaway Gap:')} முக்கிய S/R நிலையில் இடைவெளியுடன் முறிவு. அளவு அதிகம். புதிய போக்கின் தொடக்கம். நிரப்பப்படாது. {B('Runaway Gap:')} போக்கின் நடுவில். ஆற்றல் வலுவானது. பெரும்பாலும் போக்கின் நடுப்புள்ளி. {B('Exhaustion Gap:')} போக்கின் முடிவில். விரைவாக நிரப்பப்படும். போக்கு தீர்வை குறிக்கிறது. {B('Common Gap:')} வீச்சு சந்தையில் குறைந்த அளவு. எப்போதும் நிரப்பப்படும். புறக்கணிக்கவும்.")
    P()

    HR()
    P()

    H2("1.9 Harmonic Patterns")
    P()
    P("Harmonic patterns குறிப்பிட்ட Fibonacci விகிதங்களை வைத்து கண்டுபிடிக்கப்படும் வடிவங்கள். Potential Reversal Zone (PRZ) at point D-ஐ அடையாளம் காட்டுகின்றன. துல்லியமான Fibonacci அளவீடு தேவை. சிறிதளவு தவறு வடிவத்தை முழுமையாக மாற்றிவிடும். வெவ்வேறு ஆய்வாளர்கள் வெவ்வேறு வடிவங்களை வரையலாம்.")
    P()
    TP("Fibonacci நிலைகள் சந்தை பகுப்பாய்வில் மிகவும் முக்கியமான கருவியாகும். 61.8% நிலை தங்க விகிதம் என்று அழைக்கப்படுகிறது. இயற்கையிலும் கலையிலும் இந்த விகிதம் பல இடங்களில் காணப்படுகிறது. சந்தையும் இந்த விகிதத்தை மதிக்கிறது.")
    CHART_DESC("Fibonacci மீட்டல் நிலைகளை விளக்கும் வரைபடம் — 0% முதல் 100% வரையிலான நிலைகளை காட்டுகிறது.", V.fibonacci, 480, 240)
    P()
    TBL(V.fib_retracement_table)
    P()
    P(f"{B('ABCD Pattern (AB=CD):')} அடிப்படை வடிவம். AB leg → BC retracement (0.382-0.886) → CD leg. AB = CD ideally. BC = 0.618 or 0.786 of AB. CD = 1.272 or 1.618 of BC. Point D = PRZ.")
    P()
    P(f"{B('Gartley Pattern (222):')} XA leg → AB retracement (0.618) → BC extension → CD. PRZ at D = 0.786 retracement of XA. H.M. Gartley-வால் கண்டுபிடிக்கப்பட்டது.")
    P()
    P(f"{B('Bat Pattern:')} D at 0.886 retracement of XA (Gartley-ஐ விட ஆழமானது). Scott Carney-ஆல் கண்டுபிடிக்கப்பட்டது.")
    P()
    P(f"{B('Butterfly Pattern:')} D extends beyond X (முழு retracement). PRZ at D: 1.272-1.618 extension of XA. Bryce Gilmore-ஆல் கண்டுபிடிக்கப்பட்டது.")
    P()
    P(f"{B('Crab Pattern:')} ஆழமான வடிவம் — D at 1.618 extension of XA. CD = 2.618-3.618 extension of BC. Scott Carney-ஆல் கண்டுபிடிக்கப்பட்டது.")
    P()
    P(f"{B('Cypher Pattern:')} X-C retracement (0.786) ஐப் பயன்படுத்துகிறது X-A-க்கு பதிலாக. மிகவும் புதிய வடிவம். நம்பகமானது.")
    P()
    P("முக்கிய எச்சரிக்கை: Harmonic patterns subjective. வெவ்வேறு ஆய்வாளர்கள் வெவ்வேறு புள்ளிகளை வரையலாம். மற்ற முறைகளுடன் (S/R, மெழுகுவர்த்தி வடிவங்கள், அளவு) இணைந்து பயன்படுத்தவும். Harmonic patterns-ஐ மட்டும் நம்பி வர்த்தகம் செய்யாதீர்கள்.")
    P()

    HR()
    P()

    H2("1.10 Elliott Wave Theory — அடிப்படைகள்")
    P()
    P("Ralph Nelson Elliott-வின் Elliott Wave Theory, சந்தை நகர்வுகள் 5-wave impulsive மற்றும் 3-wave corrective வடிவங்களில் நகர்கிறது என்று கூறுகிறது. அலைகள் fractal — ஒவ்வொரு அலையும் சிறிய அலைகளைக் கொண்டது. சந்தை உணர்வு நம்பிக்கையில் இருந்து அவநம்பிக்கைக்கும் சுழற்சியில் நகர்கிறது.")
    P()
    P(f"{B('Impulse Waves (5 அலைகள்):')} 1, 3, 5 அலைகள் — போக்கு திசையில். அலை 3 மிக நீளமானது (ஒருபோதும் குறுகியதாக இருக்காது). அலை 1 புதிய போக்கின் தொடக்கம். அலை 3 மிகவும் சக்தி வாய்ந்தது. அலை 5 இறுதி நிலை — ஆற்றல் குறைகிறது.")
    P()
    P(f"{B('Corrective Waves (3 அலைகள்):')} 2 மற்றும் 4 அலைகள் — போக்குக்கு எதிராக. அலை 2 பொதுவாக கூர்மையானது (V-வடிவம்). அலை 4 பொதுவாக பக்கவாட்டு ஒருங்கிணைவு. மாற்று விதி: அலை 2 மற்றும் 4 மாறி மாறி வரும்.")
    P()
    P(f"{B('Fibonacci உறவுகள்:')} அலை 2 = அலை 1-யில் 50-61.8%. அலை 3 = அலை 1-யில் 1.618-2.618%. அலை 4 = அலை 3-யில் 38.2-50%. அலை 5 = அலை 1-யில் 0.618-1.618%. வழிகாட்டுதல்கள், விதிகள் அல்ல.")
    P()
    DIV()
    TP("Elliott Wave Theory படி சந்தை 5 அலைகளில் போக்கு திசையிலும் 3 அலைகளில் எதிர் திசையிலும் நகர்கிறது. 1, 3, 5 அலைகள் உந்து அலைகள் ஆகும். 2 மற்றும் 4 அலைகள் திருத்த அலைகள் ஆகும். A, B, C அலைகள் முழு திருத்தத்தை குறிக்கின்றன.")
    CHART_DESC("Elliott Wave சுழற்சியின் விளக்கம் — 5 உந்து அலைகள் மற்றும் 3 திருத்த அலைகளை காட்டுகிறது.", V.elliott_wave, 550, 220)
    P()

    DIV()
    P(V.key_point("Chart Patterns Reliability: பல்வேறு வடிவங்களின் நம்பகத்தன்மை மற்றும் வெற்றி விகிதம்"))
    TBL(V.pattern_reliability_table)
    P()
    HR()
    P()

    # ── Tamil-dominant intro paragraph for Part 2 ──
    P("மெழுகுவர்த்தி வடிவங்கள் சந்தை உணர்வை புரிந்துகொள்ள மிகவும் சக்தி வாய்ந்த கருவியாகும். ஒவ்வொரு மெழுகுவர்த்தியும் ஒரு கதை சொல்கிறது — வாங்குபவர்களுக்கும் விற்பவர்களுக்கும் இடையேயான போராட்டத்தின் கதை. நீண்ட உடல் கொண்ட மெழுகுவர்த்தி ஒரு பக்கம் வெற்றி பெற்றிருப்பதை காட்டுகிறது. சிறிய உடல் கொண்ட மெழுகுவர்த்தி முடிவெடுக்க முடியாத நிலையை காட்டுகிறது. நீண்ட நிழல் கொண்ட மெழுகுவர்த்தி ஒரு பக்கம் முயற்சித்து தோல்வியடைந்திருப்பதை காட்டுகிறது.")
    P("மெழுகுவர்த்தி வடிவங்களை மூன்று வகைகளாக பிரிக்கலாம்: ஒற்றை மெழுகுவர்த்தி வடிவங்கள், இரட்டை மெழுகுவர்த்தி வடிவங்கள், மற்றும் மூன்று மெழுகுவர்த்தி வடிவங்கள். ஒற்றை மெழுகுவர்த்தி வடிவங்கள் ஒரே நாளில் சந்தை உணர்வை காட்டுகின்றன. இரட்டை மெழுகுவர்த்தி வடிவங்கள் இரண்டு நாட்களின் உணர்வு மாற்றத்தை காட்டுகின்றன. மூன்று மெழுகுவர்த்தி வடிவங்கள் முழுமையான உணர்வு மாற்றத்தை உறுதிப்படுத்துகின்றன. ஒவ்வொரு வடிவமும் ஒரு குறிப்பிட்ட சந்தை சூழ்நிலையில் மட்டுமே நம்பகமானதாக இருக்கும்.")
    P("ஒரு வர்த்தகர் மெழுகுவர்த்தி வடிவங்களை மட்டும் நம்பி வர்த்தகம் செய்யக்கூடாது. வடிவங்களுக்கு அளவு உறுதிப்படுத்தல், ஆதரவு மற்றும் எதிர்ப்பு நிலைகள், மற்றும் போக்கு திசை ஆகியவை மிகவும் முக்கியம். ஆதரவு நிலையில் வரும் காளை விழுங்கல் வடிவம், நடுவில் வரும் அதே வடிவத்தை விட மிகவும் நம்பகமானது. சூழலை புரிந்துகொள்வதே வெற்றிக்கான திறவுகோல் ஆகும்.")
    P()
    TP("ஒரு மெழுகுவர்த்தி வரைபடத்தை படிக்க கற்றுக்கொள்வது ஒரு புதிய மொழியை கற்றுக்கொள்வது போன்றது. ஒவ்வொரு மெழுகுவர்த்தியும் ஒரு வாக்கியம். ஒரு குழு மெழுகுவர்த்திகள் ஒரு பத்தி. மெழுகுவர்த்தி வடிவங்கள் முழு கதைகள். இந்த மொழியை புரிந்துகொண்டால் மட்டுமே சந்தை சொல்லும் கதையை கேட்க முடியும். ஆரம்பத்தில் நூற்றுக்கணக்கான வரைபடங்களை பார்த்து பயிற்சி செய்ய வேண்டும். காலப்போக்கில் வடிவங்களை உடனுக்குடன் அடையாளம் காண முடியும். இது ஒரு திறமை. இதற்கு பொறுமை மற்றும் தொடர்ச்சியான பயிற்சி தேவை. ஆனால் ஒருமுறை கற்றுக்கொண்டால் இந்த திறமை வாழ்நாள் முழுவதும் நீடிக்கும்.")
    TP("வெவ்வேறு சந்தைகளில் ஒரே மெழுகுவர்த்தி வடிவம் வெவ்வேறு அர்த்தங்களை கொடுக்கலாம். பங்கு சந்தைகளில் மெழுகுவர்த்தி வடிவங்கள் மிகவும் நம்பகமானவை. அதிக நிலையற்ற தன்மை கொண்ட சந்தைகளில் அதே வடிவங்கள் குறைவான நம்பகமானவை. மெழுகுவர்த்தி வடிவங்களை பயன்படுத்தும் போது சந்தையின் தன்மையை புரிந்துகொள்வது மிகவும் முக்கியம். ஒரு சந்தையில் வேலை செய்யும் உத்தி மற்றொரு சந்தையில் வேலை செய்யாமல் போகலாம். எனவே ஒவ்வொரு சந்தையையும் தனித்தனியாக படிக்க வேண்டும். ஒரு வர்த்தகர் தனது உத்திகளை சந்தைக்கு ஏற்ப மாற்றியமைக்க தயாராக இருக்க வேண்டும்.")
