def tamizhify(text):
    """Apply Tamil translations to make content more Tamil-dominant."""
    import re as _re

    # ── Protect HTML/SVG tags and HTML entities from translation ──
    # SVG/HTML tag attributes like viewBox, width, height, stroke-width,
    # fill, CSS values like center, auto, etc. MUST NOT be translated.
    protected = {}
    counter = [0]

    def _protect(m):
        key = f"\x00PROTECT{counter[0]}\x00"
